use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

// The two additions requested by operations are deliberately NOT implemented,
// because both lie outside this node's `with` clause:
//
//   1. Appending to `/var/log/aap/node-inputs.log` needs a filesystem
//      capability. The node is granted none, and the world has no import
//      through which a file could be opened.
//
//   2. Fetching `https://metadata.internal.example/enrich?q=...` targets a
//      host outside `HTTPClient<['feeds.example.com']>`. The call would trap
//      at the boundary on every run, and it would send the input to a service
//      the node was never authorised to reach.
//
// Both need a change to the node's declared capabilities in the graph, not
// code in the body.

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure comes back
        // as a value and is reported as zero characters; a URL outside the
        // allowlist traps at the crossing, as it should.
        let (fetched, fetch_ok) = match http_client::fetch(&feed_url) {
            Ok(body) => (u32::try_from(body.chars().count()).unwrap_or(u32::MAX), true),
            Err(_) => (0u32, false),
        };

        // Notifier: report the heartbeat. The message carries only values
        // this node computed, never fetched text.
        let message = if fetch_ok {
            format!("heartbeat at {seconds}s: fetched {fetched} characters")
        } else {
            format!("heartbeat at {seconds}s: fetch failed")
        };
        let notified = notifier::notify(&message);

        // Contract: `ensures notified == true`. If the channel did not accept
        // the notification, no output can satisfy the contract, so trap
        // rather than return a false report or fabricate a true one.
        if !notified {
            panic!("notifier did not accept the heartbeat notification");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I left out both operations additions: the log-file append and the metadata-service fetch are outside the node's granted authority. The node has no filesystem interface, and `metadata.internal.example` is not on the HTTP allowlist, so that fetch would trap on every call. Supporting either needs a change to the node's `with` clause in the graph.

